#!/usr/bin/env python3
"""Persistent HTTP key-value service (dependency-free, Python 3.11+)."""

from __future__ import annotations

import argparse
import json
import os
import signal
import sys
import threading
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any

MAX_BODY_BYTES = 1 << 20  # 1 MiB


class Store:
    """Thread-safe persistent KV store backed by a JSON file with atomic replacement."""

    def __init__(self, path: str) -> None:
        self.path = path
        self._lock = threading.Lock()
        self._data: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        try:
            with open(self.path, "r", encoding="utf-8") as fh:
                raw = json.load(fh)
            if not isinstance(raw, dict):
                raise ValueError("store file root is not an object")
            now = time.time()
            cleaned: dict[str, dict[str, Any]] = {}
            for k, v in raw.items():
                if not isinstance(k, str):
                    continue
                if not isinstance(v, dict) or "value" not in v:
                    continue
                exp = v.get("expires_at")
                if exp is not None and not isinstance(exp, (int, float)):
                    continue
                if exp is not None and exp <= now:
                    continue
                cleaned[k] = {"value": v["value"], "expires_at": v.get("expires_at")}
            self._data = cleaned
        except FileNotFoundError:
            self._data = {}
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            sys.stderr.write(f"[store] failed to load {self.path}: {exc}\n")
            self._data = {}

    def _persist_locked(self) -> None:
        tmp = self.path + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump(self._data, fh, ensure_ascii=False)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, self.path)
        except OSError as exc:
            sys.stderr.write(f"[store] failed to persist {self.path}: {exc}\n")

    @staticmethod
    def _expired(entry: dict[str, Any], now: float) -> bool:
        exp = entry.get("expires_at")
        return exp is not None and exp <= now

    def get(self, key: str) -> Any | None:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return None
            if self._expired(entry, time.time()):
                del self._data[key]
                self._persist_locked()
                return None
            return entry["value"]

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        now = time.time()
        expires_at = now + ttl_seconds if ttl_seconds is not None else None
        with self._lock:
            existed = key in self._data and not self._expired(self._data[key], now)
            self._data[key] = {"value": value, "expires_at": expires_at}
            self._persist_locked()
            return existed

    def delete(self, key: str) -> bool:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            if self._expired(entry, time.time()):
                del self._data[key]
                self._persist_locked()
                return False
            del self._data[key]
            self._persist_locked()
            return True

    def keys(self) -> list[str]:
        now = time.time()
        changed = False
        with self._lock:
            live: list[str] = []
            for k, entry in list(self._data.items()):
                if self._expired(entry, now):
                    del self._data[k]
                    changed = True
                    continue
                live.append(k)
            if changed:
                self._persist_locked()
            live.sort()
            return live


class Handler(BaseHTTPRequestHandler):
    store: Store  # set as class attribute by make_server
    server_version = "http-kv/1.0"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write("%s - %s\n" % (self.address_string(), fmt % args))

    # --- helpers -----------------------------------------------------------
    def _send_json(self, status: int, payload: Any) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_empty(self, status: int) -> None:
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _read_body(self) -> bytes | None:
        length = self.headers.get("Content-Length")
        if length is None:
            return b""
        try:
            n = int(length)
        except ValueError:
            self._send_json(400, {"error": "invalid Content-Length"})
            return None
        if n < 0:
            self._send_json(400, {"error": "negative Content-Length"})
            return None
        if n > MAX_BODY_BYTES:
            self._send_json(413, {"error": "request body too large"})
            return None
        data = self.rfile.read(n)
        if len(data) > MAX_BODY_BYTES:
            self._send_json(413, {"error": "request body too large"})
            return None
        return data

    def _parse_json_body(self) -> Any | None:
        raw = self._read_body()
        if raw is None:
            return None
        if raw == b"":
            self._send_json(400, {"error": "empty body"})
            return None
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            self._send_json(400, {"error": "malformed JSON"})
            return None

    @staticmethod
    def _decode_key(raw: str) -> str | None:
        decoded = urllib.parse.unquote(raw)
        if "/" in decoded:
            return None
        if decoded == "":
            return None
        return decoded

    # --- routes ------------------------------------------------------------
    def do_GET(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if path == "/health":
            self._send_json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
            self._send_json(200, {"keys": self.store.keys()})
            return
        if path.startswith("/v1/kv/"):
            raw = path[len("/v1/kv/"):]
            key = self._decode_key(raw)
            if key is None:
                self._send_json(400, {"error": "invalid key"})
                return
            value = self.store.get(key)
            if value is None:
                self._send_json(404, {"error": "not found"})
                return
            self._send_json(200, {"key": key, "value": value})
            return
        self._send_json(404, {"error": "unknown route"})

    def do_PUT(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if not path.startswith("/v1/kv/"):
            self._send_json(404, {"error": "unknown route"})
            return
        raw = path[len("/v1/kv/"):]
        key = self._decode_key(raw)
        if key is None:
            self._send_json(400, {"error": "invalid key"})
            return
        body = self._parse_json_body()
        if body is None:
            return
        if not isinstance(body, dict) or "value" not in body:
            self._send_json(400, {"error": "body must be an object with 'value'"})
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None:
            if not isinstance(ttl, (int, float)) or isinstance(ttl, bool):
                self._send_json(400, {"error": "ttl_seconds must be a number"})
                return
            if not (ttl > 0 and ttl != float("inf")):
                self._send_json(400, {"error": "ttl_seconds must be finite and > 0"})
                return
        existed = self.store.put(key, body["value"], ttl)
        self._send_json(200 if existed else 201, {"key": key, "status": "ok"})

    def do_DELETE(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if not path.startswith("/v1/kv/"):
            self._send_json(404, {"error": "unknown route"})
            return
        raw = path[len("/v1/kv/"):]
        key = self._decode_key(raw)
        if key is None:
            self._send_json(400, {"error": "invalid key"})
            return
        if self.store.delete(key):
            self._send_empty(204)
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self) -> None:
        self._send_json(405, {"error": "method not allowed"})

    def do_PATCH(self) -> None:
        self._send_json(405, {"error": "method not allowed"})

    def do_HEAD(self) -> None:
        self._send_json(405, {"error": "method not allowed"})

    def do_OPTIONS(self) -> None:
        self._send_json(405, {"error": "method not allowed"})


def make_server(host: str, port: int, store: Store) -> ThreadingHTTPServer:
    Handler.store = store
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    return server


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Persistent HTTP KV service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=0)
    parser.add_argument("--data", required=True)
    args = parser.parse_args(argv)

    store = Store(args.data)
    server = make_server(args.host, args.port, store)

    stop = threading.Event()

    def handle_sigterm(signum: int, frame: Any) -> None:
        stop.set()
        server.shutdown()

    signal.signal(signal.SIGTERM, handle_sigterm)
    signal.signal(signal.SIGINT, handle_sigterm)

    actual_port = server.server_address[1]
    sys.stdout.write(f"LISTENING {actual_port}\n")
    sys.stdout.flush()

    try:
        server.serve_forever(poll_interval=0.2)
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

